INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_bangladesh-women-investors-network', 'bangladesh-women-investors-network', 'https://bdangels.co/', NULL, '["investor"]', '[]', '["https://bdangels.co/"]', '2026-08-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-women-investors-network', 'en', 'Bangladesh Women Investors Network', 'BAN''s women-led sister chapter mobilises women angel investors and applies a gender lens to pre-seed and seed deals. It focuses on expanding capital, mentoring and investor access for women-led and women-focused ventures.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-women-investors-network', 'bn', 'Bangladesh Women Investors Network', 'নারী অ্যাঞ্জেল ইনভেস্টরদের একত্র করা এবং প্রি-সিড ও সিড রাউন্ডে জেন্ডার-লেন্স দৃষ্টিকোণ থেকে বিনিয়োগ করাই BAN-এর এই সহযোগী চ্যাপ্টারের মূল কাজ। নারী-নেতৃত্বাধীন ও নারীদের লক্ষ্য করে গড়ে ওঠা উদ্যোগে মূলধন, মেন্টরিং ও ইনভেস্টর নেটওয়ার্ক বাড়ানোই এর লক্ষ্য।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/bangladesh-women-investors-network', 'org_bangladesh-women-investors-network');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('company-profile-org_bangladesh-women-investors-network', 'org_bangladesh-women-investors-network', 'import', 'editorial:company-directory', '2026-09-20', '{"source":"data/directory/investors.json","entry":"bangladesh-women-investors-network","checkedAt":"2026-08-19"}');
INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_startup-bangladesh-limited', 'startup-bangladesh-limited', 'https://www.startupbangladesh.vc/', NULL, '["investor"]', '[]', '["https://www.startupbangladesh.vc/contact/faqs/"]', '2026-08-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_startup-bangladesh-limited', 'en', 'Startup Bangladesh Limited', 'The ICT Division''s government-owned venture-capital company invests equity or quasi-equity in Bangladesh-registered startups and impact enterprises with an MVP and evidence of customer or revenue growth. It can also provide governance and operational support and co-invest with other funders.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_startup-bangladesh-limited', 'bn', 'Startup Bangladesh Limited', 'তথ্য ও যোগাযোগ প্রযুক্তি বিভাগের মালিকানাধীন এই সরকারি ভেঞ্চার ক্যাপিটাল কোম্পানিটি বাংলাদেশে নিবন্ধিত স্টার্টআপ ও ইমপ্যাক্ট উদ্যোগে ইকুইটি বা কোয়াসি-ইকুইটির মাধ্যমে বিনিয়োগ করে। আবেদনকারী প্রতিষ্ঠানের একটি তৈরি এমভিপি (MVP) এবং কাস্টমার বা আয় বৃদ্ধির বাস্তব প্রমাণ থাকতে হয়। এটি প্রাতিষ্ঠানিক সুশাসন ও পরিচালন সহায়তার পাশাপাশি অন্যান্য ইনভেস্টরের সাথে যৌথ বিনিয়োগও করে থাকে।');
