INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_anchorless-bangladesh', 'anchorless-bangladesh', 'https://anchorless.vc/', NULL, '["investor"]', '[]', '["https://www.anchorless.vc/portfolio"]', '2026-08-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_anchorless-bangladesh', 'en', 'Anchorless Bangladesh', 'A Bangladesh-focused early-stage fund investing primarily in seed rounds, with selective pre-seed and post-seed deals. It looks for companies with a technology or data advantage, scalable models, international expansion potential and a credible path to follow-on funding and exit.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_anchorless-bangladesh', 'bn', 'Anchorless Bangladesh', 'বাংলাদেশ-কেন্দ্রিক এই প্রারম্ভিক পর্যায়ের ফান্ডটি মূলত সিড রাউন্ডে বিনিয়োগ করে, সাথে বাছাইকৃত কিছু প্রি-সিড ও পোস্ট-সিড ডিলেও অংশ নেয়। যেসব কোম্পানির প্রযুক্তি বা ডেটায় শক্ত অবস্থান, স্কেল করার মতো মডেল, আন্তর্জাতিক বাজারে বিস্তারের সুযোগ এবং পরবর্তী রাউন্ডে ফান্ডিং ও এক্সিটের পরিষ্কার রূপরেখা রয়েছে, তারা সেগুলোতে গুরুত্ব দেয়।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/anchorless-bangladesh', 'org_anchorless-bangladesh');
