INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_bangladesh-startup-investment-company-plc-bsic', 'bangladesh-startup-investment-company-plc-bsic', 'https://www.bsic.vc/', NULL, '["investor"]', '[]', '["https://www.bsic.vc/"]', '2026-08-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-startup-investment-company-plc-bsic', 'en', 'Bangladesh Startup Investment Company PLC (BSIC)', 'A permanent venture-capital vehicle funded by 39 Bangladeshi commercial banks. Its US$35 million ONKUR fund is designed to co-invest in high-growth Bangladesh startups alongside a credible global or regional lead investor.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-startup-investment-company-plc-bsic', 'bn', 'Bangladesh Startup Investment Company PLC (BSIC)', 'বাংলাদেশের ৩৯টি বাণিজ্যিক ব্যাংকের অর্থায়নে গঠিত একটি স্থায়ী ভেঞ্চার ক্যাপিটাল প্রতিষ্ঠান। এদের ৩৫ মিলিয়ন ডলারের ONKUR ফান্ডটি কোনো নির্ভরযোগ্য বৈশ্বিক বা আঞ্চলিক লিড ইনভেস্টরের পাশাপাশি সম্ভাবনাময় বাংলাদেশি স্টার্টআপে যৌথ বিনিয়োগ (co-invest) করার জন্য তৈরি।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/bangladesh-startup-investment-company-plc-bsic', 'org_bangladesh-startup-investment-company-plc-bsic');
