INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_dekko-isho-venture-capital-divc', 'dekko-isho-venture-capital-divc', 'https://www.di.vc/', NULL, '["investor"]', '[]', '["https://www.di.vc/"]', '2026-08-25', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_dekko-isho-venture-capital-divc', 'en', 'Dekko ISHO Venture Capital (DIVC)', 'A founder-focused venture investor backed by Dekko ISHO Group. It provides capital and hands-on support across strategy, operations, legal, hiring, branding and growth.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_dekko-isho-venture-capital-divc', 'bn', 'Dekko ISHO Venture Capital (DIVC)', 'Dekko ISHO Group-এর সমর্থনে পরিচালিত এই ভেঞ্চার ইনভেস্টর ফাউন্ডারদের প্রয়োজনকে অগ্রাধিকার দেয়। মূলধনের পাশাপাশি স্ট্র্যাটেজি, অপারেশন, আইনি কাজ, নিয়োগ, ব্র্যান্ডিং ও গ্রোথে হাতে-কলমে সহায়তা করে।');
