INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_bangladesh-venture-capital-limited-bvcl', 'bangladesh-venture-capital-limited-bvcl', 'https://venture.com.bd/', NULL, '["investor"]', '[]', '["https://venture.com.bd/portfolio/"]', '2026-08-25', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-venture-capital-limited-bvcl', 'en', 'Bangladesh Venture Capital Limited (BVCL)', 'A Bangladesh venture-capital and alternative-investment company providing capital, mentorship, industry connections and strategic guidance to startups and growth-stage businesses.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_bangladesh-venture-capital-limited-bvcl', 'bn', 'Bangladesh Venture Capital Limited (BVCL)', 'বাংলাদেশের একটি ভেঞ্চার-ক্যাপিটাল আর অল্টারনেটিভ-ইনভেস্টমেন্ট কোম্পানি। এরা স্টার্টআপ আর গ্রোথ-স্টেজ কোম্পানিগুলোতে মূলধনের পাশাপাশি মেন্টরশিপ, ইন্ডাস্ট্রি নেটওয়ার্ক আর স্ট্র্যাটেজিক সাপোর্ট দেয়।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/bangladesh-venture-capital-limited-bvcl', 'org_bangladesh-venture-capital-limited-bvcl');
