INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_yy-ventures', 'yy-ventures', 'https://yy.ventures/', NULL, '["investor"]', '[]', '["https://yy.ventures/funds"]', '2026-08-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_yy-ventures', 'en', 'YY Ventures', 'An impact investor and venture-support company for early-stage social businesses addressing challenges such as carbon emissions, poverty and unemployment in Bangladesh. It combines capital with hands-on help securing partners, customers and follow-on investors.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_yy-ventures', 'bn', 'YY Ventures', 'বাংলাদেশে কার্বন নিঃসরণ কমানো, দারিদ্র্য দূর করা ও বেকারত্ব দূর করতে কাজ করা প্রাথমিক পর্যায়ের সামাজিক ব্যবসাগুলোতে বিনিয়োগ ও সার্বিক সহায়তা দেয় YY Ventures। মূলধনের পাশাপাশি পার্টনারশিপ, কাস্টমার তৈরি এবং পরবর্তী রাউন্ডের ইনভেস্টর পেতে এরা নিবিড়ভাবে কাজ করে।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/yy-ventures', 'org_yy-ventures');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('company-profile-org_yy-ventures', 'org_yy-ventures', 'import', 'editorial:company-directory', '2026-09-20', '{"source":"data/directory/investors.json","entry":"yy-ventures","checkedAt":"2026-08-19"}');
INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_accelerating-asia-ventures', 'accelerating-asia-ventures', 'https://www.acceleratingasia.com/', NULL, '["investor"]', '[]', '["https://www.acceleratingasia.com/getfunded"]', '2026-08-19', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_accelerating-asia-ventures', 'en', 'Accelerating Asia Ventures', 'A Singapore-based VC accelerator investing in high-growth, pre-Series A technology startups across South and Southeast Asia. Investment is tied to its 100-day accelerator; participating companies pay a US$35,000 programme fee and give 3% equity, separate from the post-money SAFE investment terms.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_accelerating-asia-ventures', 'bn', 'Accelerating Asia Ventures', 'সিঙ্গাপুর-ভিত্তিক এই ভিসি অ্যাক্সিলারেটর দক্ষিণ ও দক্ষিণ-পূর্ব এশিয়ার উচ্চ সম্ভাবনাময় প্রি-সিরিজ এ প্রযুক্তি স্টার্টআপে বিনিয়োগ করে। বিনিয়োগের শর্ত হিসেবে ১০০ দিনের অ্যাক্সিলারেটর প্রোগ্রামে অংশ নিতে হয়। অংশগ্রহণকারী কোম্পানিকে ৩৫,০০০ ডলার প্রোগ্রাম ফি এবং ৩% ইকুইটি দিতে হয় (যা তাদের পোস্ট-মানি SAFE বিনিয়োগ চুক্তির বাইরে পৃথক শর্ত)।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/accelerating-asia-ventures', 'org_accelerating-asia-ventures');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('company-profile-org_accelerating-asia-ventures', 'org_accelerating-asia-ventures', 'import', 'editorial:company-directory', '2026-09-20', '{"source":"data/directory/investors.json","entry":"accelerating-asia-ventures","checkedAt":"2026-08-19"}');
INSERT INTO organizations (id, slug, website, logo_path, roles_json, aliases_json, sources_json, source_date, origin) VALUES ('org_idlc-venture-capital', 'idlc-venture-capital', 'https://www.idlcvc.com/', NULL, '["investor"]', '[]', '["https://www.idlcvc.com/coming-soon-03","https://www.idlcvc.com/thesis","https://www.idlcvc.com/"]', '2026-09-11', 'editorial-import');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_idlc-venture-capital', 'en', 'IDLC Venture Capital', 'A Bangladesh-focused investor in early-stage technology and technology-enabled companies. Its published portfolio remains useful for research, but it is not a current funding route. The manager says it plans another fund in 2027; that is a plan, not an open call.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_idlc-venture-capital', 'bn', 'IDLC Venture Capital', 'বাংলাদেশের আর্লি স্টেজ প্রযুক্তিনির্ভর কোম্পানিতে ইনভেস্ট করে। পুরোনো পোর্টফোলিও থেকে ধারণা নিতে পারেন, তবে এখন এখানে ফান্ডিংয়ের আবেদন করা যাচ্ছে না। প্রতিষ্ঠানটি ২০২৭ সালে আরেকটি ফান্ড চালুর পরিকল্পনা জানিয়েছে। সেটা পরিকল্পনা, আবেদন শুরুর ঘোষণা নয়।');
INSERT INTO identity_references (namespace, external_id, organization_id) VALUES ('directory', 'investors/idlc-venture-capital', 'org_idlc-venture-capital');
INSERT INTO identity_events (id, organization_id, action, actor, created_at, detail_json) VALUES ('company-profile-org_idlc-venture-capital', 'org_idlc-venture-capital', 'import', 'editorial:company-directory', '2026-09-20', '{"source":"data/directory/investors.json","entry":"idlc-venture-capital","checkedAt":"2026-09-11"}');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_10-minute-school', '{"sections":[{"id":"products","title":{"en":"Products & services","bn":"প্রোডাক্ট ও সেবা"},"body":{"en":"10 Minute School offers academic courses, exam preparation, English and practical skills courses alongside free educational content. Learners can use recorded lessons, live classes and practice materials through its app.","bn":"10 Minute School-এ স্কুলের পড়াশোনা, পরীক্ষার প্রস্তুতি, ইংরেজি ও কাজের দক্ষতা শেখার কোর্স আছে। বিনা মূল্যের শিক্ষামূলক কনটেন্টও পাওয়া যায়। অ্যাপে রেকর্ড করা পাঠ, লাইভ ক্লাস ও অনুশীলনের উপকরণ ব্যবহার করা যায়।"},"sources":[{"title":"10 Minute School - courses and support","url":"https://10minuteschool.com/","publishedOn":null,"checkedAt":"2026-09-20"}],"links":[]}],"contact":{"address":null,"email":null,"phone":"16910","sources":[{"title":"10 Minute School - courses and support","url":"https://10minuteschool.com/","publishedOn":null,"checkedAt":"2026-09-20"}]}}', '2026-09-20');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_bangladesh-angels-network', '{"sections":[{"id":"network","title":{"en":"How the network works","bn":"নেটওয়ার্কটি যেভাবে কাজ করে"},"body":{"en":"BAN connects founders with angel investors and helps them prepare for fundraising, including investor readiness and cap-table advice. Members make their own investment decisions. BAN says it does not pool member capital into a fund.","bn":"ফান্ড সংগ্রহের প্রস্তুতি নিতে ও অ্যাঞ্জেল ইনভেস্টরদের সঙ্গে যোগাযোগ করতে ফাউন্ডারদের সাহায্য করে BAN। বিনিয়োগের প্রস্তুতি ও ক্যাপ টেবিল নিয়েও পরামর্শ দেয়। বিনিয়োগ করবেন কি না, সেই সিদ্ধান্ত সদস্যরা নিজেরাই নেন। BAN-এর ভাষ্য অনুযায়ী, সদস্যদের টাকা একত্র করে কোনো ফান্ড চালায় না তারা।"},"sources":[{"title":"About Bangladesh Angels Network","url":"https://bdangels.co/about-us","publishedOn":null,"checkedAt":"2026-09-20"}],"links":[]},{"id":"apply","title":{"en":"For founders raising capital","bn":"ফান্ড সংগ্রহ করতে চাইলে"},"body":{"en":"Review the network’s application process and submit through its official founder route. Interest from the network is not a funding commitment.","bn":"আবেদনের নিয়মগুলো দেখে BAN-এর নিজস্ব ওয়েবসাইটে তথ্য জমা দিন। নেটওয়ার্ক আগ্রহ দেখালেই বিনিয়োগের প্রতিশ্রুতি দিয়েছে, এমন ধরে নেবেন না।"},"sources":[{"title":"BAN - founder application","url":"https://bdangels.co/startups","publishedOn":null,"checkedAt":"2026-09-20"}],"links":[{"label":{"en":"Founder application","bn":"ফাউন্ডারদের আবেদন"},"url":"https://bdangels.co/startups"}]}],"contact":{"address":{"en":"Level 3, House 27, Road 12, Niketon Housing Society, Gulshan 1, Dhaka 1212, Bangladesh.","bn":"লেভেল ৩, বাড়ি ২৭, রোড ১২, নিকেতন হাউজিং সোসাইটি, গুলশান ১, ঢাকা ১২১২, বাংলাদেশ।"},"email":"hello@bdangels.co","phone":null,"sources":[{"title":"About Bangladesh Angels Network","url":"https://bdangels.co/about-us","publishedOn":null,"checkedAt":"2026-09-20"}]}}', '2026-09-20');
INSERT INTO organization_profiles (organization_id, profile_json, reviewed_at) VALUES ('org_shopup-silq', '{"sections":[{"id":"products","title":{"en":"Products & services","bn":"প্রোডাক্ট ও সেবা"},"body":{"en":"ShopUp connects neighbourhood retailers with sourcing, logistics and finance. Its product offering includes Mokam, a B2B commerce platform, and REDX, a logistics service.","bn":"পাড়ার দোকানগুলোর পণ্য সংগ্রহ, পরিবহন ও অর্থায়ন নিয়ে কাজ করে ShopUp। তাদের সেবার মধ্যে আছে বিটুবি কমার্স প্ল্যাটফর্ম Mokam ও লজিস্টিকস সেবা REDX।"},"sources":[{"title":"ShopUp - products, leadership and offices","url":"https://www.shopup.org/about","publishedOn":null,"checkedAt":"2026-09-20"}],"links":[{"label":{"en":"Mokam","bn":"Mokam"},"url":"https://mokam.com.bd/"},{"label":{"en":"REDX","bn":"REDX"},"url":"https://redx.com.bd/"}]},{"id":"structure","title":{"en":"ShopUp and SILQ","bn":"ShopUp ও SILQ"},"body":{"en":"ShopUp and Sary combined to form SILQ in 2025. This profile covers the Bangladesh operation and explains the wider group context. Group or transaction financing should not be read as equity raised solely by ShopUp in Bangladesh.","bn":"২০২৫ সালে ShopUp ও Sary মিলে SILQ গড়ে তোলে। এখানে বাংলাদেশের কার্যক্রমের পাশাপাশি বৃহত্তর গ্রুপের প্রেক্ষাপটও দেওয়া আছে। গ্রুপ বা এই একীভূত হওয়ার অর্থায়নকে শুধু বাংলাদেশের ShopUp-এর ইকুইটি বিনিয়োগ ধরে নেওয়া ঠিক হবে না।"},"sources":[{"title":"ShopUp - products, leadership and offices","url":"https://www.shopup.org/about","publishedOn":null,"checkedAt":"2026-09-20"}],"links":[]}],"contact":{"address":{"en":"429–432, Tejgaon I/A, Dhaka 1208, Bangladesh.","bn":"৪২৯–৪৩২, তেজগাঁও শিল্প এলাকা, ঢাকা ১২০৮, বাংলাদেশ।"},"email":"hello@shopup.org","phone":null,"sources":[{"title":"ShopUp - products, leadership and offices","url":"https://www.shopup.org/about","publishedOn":null,"checkedAt":"2026-09-20"}]}}', '2026-09-20');
