INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_silq', 'en', 'SILQ', 'Group formed through the combination of ShopUp and Sary in 2025, connecting commerce operations in the Gulf and Bangladesh.');
INSERT INTO organization_text (organization_id, locale, name, description) VALUES ('org_silq', 'bn', 'SILQ', '২০২৫ সালে ShopUp ও Sary মিলে গড়ে ওঠা গ্রুপ। উপসাগরীয় অঞ্চল ও বাংলাদেশের কমার্স কার্যক্রম এই গ্রুপের অধীনে যুক্ত হয়েছে।');
